class StatusChangedException(Exception):
    """Raised when monitored status changes during observation period."""
    pass


class DeltaHelper:
    """
    Helper for creating delta operations for BTS configuration.
    """
    def __init__(self, admin_cli):
        self.admin_cli = admin_cli
        self.scf_util = scf()
        self.log_dir = get_builtin_value('OUTPUT_DIR')
        self.initial_scf_file_name = 'ESM_initial_scf.xml'
        self.current_scf_file_name = 'ESM_current_scf.xml'
        self.scf_delta_file_name = 'ESM_restore_scf_delta.json'

    def backup_initial_scf(self, connection):
        self.initial_scf_path = self._get_current_scf_file(connection=connection, file_name=self.initial_scf_file_name)

    def _get_current_scf_file(self, connection, file_name):
        return self.admin_cli.get_current_scf_file(
            local_dir_path=self.log_dir,
            file_name=file_name,
            connection=connection, timeout=90)

    @log_as_robot_keyword
    def calculate_delta_to_initial_scf(self, current_scf_path):
        delta_scf_path = os.path.join(self.log_dir, self.scf_delta_file_name)
        self.scf_util.calculate_delta_scf(
            target_scf_path=self.initial_scf_path,
            actual_scf_path=current_scf_path,
            delta_scf_path=delta_scf_path
        )
        return delta_scf_path

    def recommission_to_initial_state(self, connection):
        current_scf_path = self._get_current_scf_file(connection=connection, file_name=self.current_scf_file_name)
        delta_scf_path = self.calculate_delta_to_initial_scf(current_scf_path=current_scf_path)
        log_info_to_console("Recommission to initial state ...")
        self.admin_cli.perform_delta_recommissioning(delta_file=delta_scf_path, connection=connection)

    @log_as_robot_keyword
    def get_delta_for_esm1_state(self, connection, configuration):
        # Use unified helper for ESM1
        return self._get_delta_for_esm_state(connection=connection, configuration=configuration, esm_state='ESM1')

    @log_as_robot_keyword
    def get_delta_for_esm2_state(self, connection, configuration):
        # Use unified helper for ESM2 and add deep sleep schedule delta
        return self._get_delta_for_esm_state(connection=connection, configuration=configuration, esm_state='ESM2')

    def _get_delta_for_esm_state(self, connection, configuration, esm_state):
        """
        Returns delta to enable energy saving for power groups and RUs as per ESM configuration.

        :param connection: Connection object to the BTS.
        :param configuration: Full configuration dict containing ESM1/ESM2.
        :param esm_state: 'ESM1' or 'ESM2'
        :return: List of delta dicts.
        """
        delta = []
        esm_config = configuration.get(esm_state, {})
        enabled_lbps_period = self._get_lbps_period_list(suspended=False)
        disabled_lbps_period = self._get_lbps_period_list(suspended=True)
        cell_power_grps = self.get_mapping_cells_to_power_groups(connection=connection)

        # Only one record per pgrp_dist_name (multiple cell_name may map to the same pgrp)
        pgrp_records = {}  # pgrp_dist_name -> (param_names, param_values, first_cell_name)
        for cell_name in cell_power_grps:
            pgrp_dist_name = cell_power_grps[cell_name]
            if cell_name in esm_config:
                cell_params = esm_config[cell_name]
                param_names = list(cell_params.keys())
                param_values = list(cell_params.values())
                param_names.insert(0, 'lbpsPeriodList')
                param_values.insert(0, [enabled_lbps_period])
            else:
                param_names = ['lbpsPeriodList']
                param_values = [[disabled_lbps_period]]

            if pgrp_dist_name in pgrp_records:
                existing_names, existing_values, first_cell_name = pgrp_records[pgrp_dist_name]
                if (param_names, param_values) != (existing_names, existing_values):
                    raise ValueError(
                        f"Different ESM parameters for the same power group {pgrp_dist_name}: "
                        f"parameters from cell '{first_cell_name}' (already recorded) vs different parameters from cell '{cell_name}'.\n"
                        f"Expected from '{first_cell_name}' (names, values): ({existing_names}, {existing_values}), "
                        f"got from '{cell_name}': ({param_names}, {param_values})."
                    )
                continue
            pgrp_records[pgrp_dist_name] = (param_names, param_values, cell_name)

        for pgrp_dist_name, (param_names, param_values, _) in pgrp_records.items():
            delta.append(self._create_delta_record(
                dist_name=pgrp_dist_name,
                parameter_name=param_names,
                parameter_value=param_values
            ))

        bts_info = self.admin_cli.get_bts_info(connection=connection, timeout=90)
        rus_info = bts_info['radioModules']
        rus_to_update = [
            ru_info['id']['configuration']
            for ru_type in rus_info
            for ru_info in rus_info[ru_type]
            if ru_info['status'].get('powerState') != 'UNAVAILABLE'
        ]

        for ru_dist_name in rus_to_update:
            ru_name = get_substring_from_dist_name(ru_dist_name, start=-1, end=None)
            if ru_name in esm_config:
                ru_params = esm_config[ru_name]
                param_names = list(ru_params.keys())
                param_values = list(ru_params.values())
                delta.append(self._create_delta_record(
                    dist_name=ru_dist_name,
                    parameter_name=param_names,
                    parameter_value=param_values
                ))
            else:
                delta.append(self._create_delta_record(
                    dist_name=ru_dist_name,
                    parameter_name="energySavingMode",
                    parameter_value='NORMAL'
                ))

        delta += self._get_delta_to_disable_radio_deep_sleep_schedule(connection=connection)

        return delta

    @log_as_robot_keyword
    def get_mapping_cells_to_power_groups(self, connection):
        """
        Maps cells to their respective power groups.

        :param connection: Connection object/alias to the BTS.
        :return: Dict mapping cell names to power group names.
        # dist_name
            Example: {'NRCELL-1': 'NRPGRP-1', 'LNCELL-1': 'PSGRP-1'}
        """
        cell_to_pgrp_map = {}
        class_configs = [
            ("NRPGRP", "nrCellId", "NRCELL"),
            ("PSGRP", "lnCelId", "LNCEL")
        ]
        for class_name, cell_id_key, cell_prefix in class_configs:
            pgrps = self.admin_cli.get_parameter_by_class(connection=connection, class_name=class_name)
            for pgrp in pgrps:
                for lbps_cell_list in pgrp.get("parameters", {}).get("lbpsCellList", []):
                    cell_id = lbps_cell_list.get(cell_id_key)
                    if cell_id is not None:
                        cell_name = f"{cell_prefix}-{cell_id}"
                        cell_to_pgrp_map[cell_name] = pgrp['distName']
        return cell_to_pgrp_map

    @log_as_robot_keyword
    def get_delta_to_disable_energy_saving_for_all_power_groups(self, connection):
        """
        Returns delta to disable energy saving for all power groups.

        :param connection: Connection object/alias to the BTS.
        :return: List of delta dicts.
        """
        return self._get_delta_to_enable_disable_energy_saving_for_all_power_groups(connection, operation="disable")

    @log_as_robot_keyword
    def get_delta_to_disable_deep_sleep_for_all_rus(self, connection):
        """
        Returns delta to disable deep sleep for all RUs.

        :param connection: Connection object/alias to the BTS.
        :return: List of delta dicts.
        """
        return self._get_delta_to_enable_disable_deep_sleep_for_all_rus(connection, operation="disable")

    def _get_delta_to_enable_disable_energy_saving_for_all_power_groups(self, connection, operation="enable"):
        """
        Internal: Returns delta to enable/disable energy saving for all power groups.
        """
        delta = []
        suspended = operation != "enable"
        nrpgrps = self.admin_cli.get_parameter_by_class(connection=connection, class_name="NRPGRP")
        psgrps = self.admin_cli.get_parameter_by_class(connection=connection, class_name="PSGRP")
        new_lbps_period = self._get_lbps_period_list(suspended=suspended)
        for pgrp in nrpgrps + psgrps:
            dist_name = pgrp['distName']
            delta.append(self._create_delta_record(
                dist_name=dist_name,
                parameter_name="lbpsPeriodList",
                parameter_value=[new_lbps_period]
            ))
        return delta

    def _get_delta_to_disable_radio_deep_sleep_schedule(self, connection):
        """
        Internal: Returns delta to disable radio deep sleep schedule.
        """
        delta = []
        featcadms = self.admin_cli.get_parameter_by_class(connection=connection, class_name="FEATCADM")
        for featcadm in featcadms:
            dist_name = featcadm['distName']
            delta.append(self._create_delta_record(
                dist_name=dist_name,
                parameter_name="actRadioDeepSleepTimeSchedule",
                parameter_value=False
            ))
        return delta

    def _get_delta_to_enable_disable_deep_sleep_for_all_rus(self, connection, operation="enable"):
        """
        Internal: Returns delta to enable/disable deep sleep for all RUs.
        """
        value = 'DEEPSLEEP' if operation == "enable" else 'NORMAL'
        bts_info = self.admin_cli.get_bts_info(connection=connection, timeout=90)
        rus_info = bts_info['radioModules']
        rus_to_update = [
            ru_info['id']['configuration']
            for ru_type in rus_info
            for ru_info in rus_info[ru_type]
            if ru_info['status'].get('powerState') != 'UNAVAILABLE'
        ]
        return [
            self._create_delta_record(
                dist_name=ru_dist_name,
                parameter_name="energySavingMode",
                parameter_value=value
            )
            for ru_dist_name in rus_to_update
        ]

    @staticmethod
    def _create_delta_record(dist_name, parameter_name, parameter_value):
        """
        Internal: Creates a delta record for parameter update.
        """
        if not isinstance(parameter_name, list):
            parameter_name = [parameter_name]
            parameter_value = [parameter_value]

        parameters = []
        for pname, pvalue in zip(parameter_name, parameter_value):
            parameters.append({
                "parameterName": pname,
                "value": pvalue,
                "operation": "update"
            })

        return {
            "distName": dist_name,
            "operation": "update",
            "parameters": parameters
        }

    @staticmethod
    def _get_lbps_period_list(time_offset_minutes: int = 2, lbps_duration: int = 1400, suspended: bool = False):
        """
        Internal: Returns lbpsPeriodList dict for delta creation.
        """
        current_time = datetime.datetime.now() + datetime.timedelta(minutes=time_offset_minutes)
        return {
            "lbpsDayOfWeek": current_time.strftime("%a"),
            "lbpsStartTimeHour": int(current_time.strftime("%H")),
            "lbpsStartTimeMinute": int(current_time.strftime("%M")),
            "lbpsDuration": lbps_duration,
            "lbpsSuspended": "notSuspended" if not suspended else "suspended"
        }


class BtsStateManager:
    """
    Handles BTS state transitions (OnAir, ESM1, ESM2).
    """
    def __init__(self, admin_cli, delta_helper, status_checker):
        self.admin_cli = admin_cli
        self.delta_helper = delta_helper
        self.status_checker = status_checker
        self.generic_ru = GenericRuOperations()
        self.generic_cell = GenericCellOperations()

    @staticmethod
    def is_cell_object(object_name):
        return re.match(r'^(LNCEL|NRCELL)-\d+$', object_name) is not None

    @staticmethod
    def is_ru_object(object_name):
        return re.match(r'^(ASI)?RMOD-\d+$', object_name) is not None

    @staticmethod
    def get_cells_with_switch_off(configuration):
        """
        Returns a list of cell names that have 'cell switch off' as lbpsSOMethod.

        :param configuration: Dict with configuration for cells.
            Example: {'LNCELL-1': {'lbpsSOMethod': 'cell switch off'}, ...}
        :return: List of cell names.
        """
        cell_switch_off_cells = []
        for obj_name in configuration:
            if BtsStateManager.is_cell_object(obj_name):
                energy_state_mode = configuration[obj_name].get('lbpsSOMethod')
                if energy_state_mode and energy_state_mode.lower() == 'cell switch off':
                    cell_switch_off_cells.append(obj_name)
        return cell_switch_off_cells

    @staticmethod
    @log_as_robot_keyword
    def get_expected_cells_status(configuration):
        """
        Returns expected status for each cell based on configuration.

        :param configuration: Dict with configuration for cells.
            Example: {'LNCELL-1': {'lbpsSOMethod': 'cell switch off'}, ...}
        :return: Dict {cell_name: expected_status}
        """
        configuration_expected_status_mapping = {
            'tx switch off': 'reducedEnergySaving',
            'cell switch off': 'energySaving',
        }
        expected_cells_status = {}
        for obj_name in configuration:
            if BtsStateManager.is_cell_object(obj_name):
                energy_state_mode = configuration[obj_name].get('lbpsSOMethod')
                if energy_state_mode:
                    expected_cells_status[obj_name] = configuration_expected_status_mapping[energy_state_mode.lower()]
        return expected_cells_status

    @log_as_robot_keyword
    def get_expected_rus_status(self, connection, configuration):
        """
        Returns expected RU statuses based on configuration.

        :param connection: Connection object/alias to the BTS.
        :param configuration: Dict with configuration for RUs and cells.
            Example: {'RMOD-1': {'energySavingMode': 'DEEPSLEEP'}, ...}
        :return: Dict {ru_name: expected_status}
        """
        ru_cell_relations = self.generic_ru._get_ru_cell_relation(connection=connection)
        cell_names_without_nb_iot = self.generic_cell._get_all_cell_names(connection=connection, skip_nb_iot=True)
        cells_with_switch_off = self.get_cells_with_switch_off(configuration)
        wcdma_gsm_cell_blocked = configuration.get('BLOCK_WCDMA_GSM_CELLS', False)
        configuration_expected_status_mapping = {
            'DEEPSLEEP': 'SLEEP',
            'DEEPSLEEP_EXTREME_SFP': 'SLEEP_EXTREME',
        }
        expected_ru_status = {}
        for obj_name in configuration:
            if BtsStateManager.is_ru_object(obj_name):
                ru_cell_relation = [record for record in ru_cell_relations if record['name'] == obj_name][0]
                cell_names_under_ru = [record['name'] for record in ru_cell_relation['cells']]
                cell_names_under_ru_no_nb_iot = list(set(cell_names_under_ru) & set(cell_names_without_nb_iot))
                if wcdma_gsm_cell_blocked:
                    cell_names_under_ru_no_nb_iot = [
                        cell_name
                        for cell_name in cell_names_under_ru_no_nb_iot
                        if not (self.generic_cell.is_gsm_cell(cell_name) or self.generic_cell.is_wcdma_cell(cell_name))
                    ]
                if cell_names_under_ru_no_nb_iot and all(
                    cell_name in cells_with_switch_off
                    for cell_name in cell_names_under_ru_no_nb_iot
                ):
                    energy_state_mode = configuration[obj_name].get("energySavingMode")
                    expected_ru_status[obj_name] = (
                        configuration_expected_status_mapping[energy_state_mode]
                    )
        return expected_ru_status

    def _wait_for_expected_state(self, connection, configuration, state_key):
        """
        Enables ESM state and waits for cells and RUs to reach expected state.
        :param connection: Connection object to the BTS.
        :param configuration: Full configuration dict.
        :param state_key: 'ESM1' or 'ESM2'
        """
        esm_config = configuration[state_key]
        expected_cells_status = self.get_expected_cells_status(configuration=esm_config)
        expected_rus_status = self.get_expected_rus_status(connection=connection,
                                                           configuration=esm_config)
        log_info_to_console("Waiting until cells are in the expected state", log_hierarchy=3)
        self.status_checker.wait_till_cells_in_expected_state(connection=connection,
                                                              expected_cells_status=expected_cells_status,
                                                              timeout=900, interval=30)
        log_info_to_console("Waiting until RUs are in the expected state", log_hierarchy=3)
        self.status_checker.wait_till_rus_in_expected_state(connection=connection,
                                                            expected_rus_status=expected_rus_status,
                                                            timeout=900, interval=30)

    def go_to_proper_state(self, connection, test_state, configuration_yaml_file):
        """
        Changes the BTS state according to the specified test_state.
        Supported states: 'OnAirBefore', 'ESM1', 'ESM2', 'OnAirAfter'.

        :param connection: Connection object to the BTS.
        :param test_state: Desired BTS state ('OnAirBefore', 'ESM1', 'ESM2', 'OnAirAfter'). Example: 'ESM1'
        :param configuration_yaml_file: Path to YAML file with test configuration.
            Example: '/path/to/config.yaml'
        """
        configuration = self.load_configuration_yaml_file(configuration_yaml_file)['CONFIGURATION']

        if 'OnAir' in test_state:
            log_info_to_console("Disabling ESM to ensure BTS is in the OnAir state", log_hierarchy=3)
            self.enable_onair_state(connection=connection)
            log_info_to_console("Checking if cells are OnAir", log_hierarchy=3)
            wait_till_succeeds(func=self.status_checker.check_all_cells_are_on_air,
                               exception_to_catch=IncorrectCellsStatuses,
                               print_traceback=True,
                               interval=30, timeout=900,
                               connection=connection)
        elif test_state == 'ESM1':
            log_info_to_console("Enabling ESM1 state", log_hierarchy=3)
            self.enable_esm1_state(connection=connection, configuration=configuration)
            self._wait_for_expected_state(connection, configuration, test_state)
        elif test_state == 'ESM2':
            log_info_to_console("Enabling ESM2 state", log_hierarchy=3)
            self.enable_esm2_state(connection=connection, configuration=configuration)
            self._wait_for_expected_state(connection, configuration, test_state)

    @staticmethod
    def load_configuration_yaml_file(configuration_yaml_file):
        """
        Loads the configuration YAML file.

        :param configuration_yaml_file: Path to YAML file.
        :return: Parsed configuration dictionary.
        """
        with open(configuration_yaml_file, 'r') as file:
            configuration = yaml.safe_load(file)
        return configuration

    @log_as_robot_keyword
    def enable_onair_state(self, connection):
        """
        Disables energy saving and deep sleep for all groups and RUs to bring BTS to OnAir state.

        :param connection: Connection object to the BTS.
        """
        delta = (
            self.delta_helper.get_delta_to_disable_energy_saving_for_all_power_groups(connection=connection)
            + self.delta_helper.get_delta_to_disable_deep_sleep_for_all_rus(connection=connection)
        )
        self.admin_cli.perform_delta_recommissioning(delta_file=json.dumps(delta), connection=connection)
        self.unblock_wcdma_gsm_cells(connection=connection)

    @log_as_robot_keyword
    def block_wcdma_gsm_cells(self, connection):
        rat_states = self._get_rat_states(connection)
        rats = ['gsm', 'wcdma']
        for rat in rats:
            if rat_states.get(rat) in ['ALL_ENABLED', 'PARTIALLY_DISABLED']:
                self.admin_cli.block_rat(connection=connection, rat=rat.upper(), timeout=300)

    @log_as_robot_keyword
    def unblock_wcdma_gsm_cells(self, connection):
        rat_states = self._get_rat_states(connection)
        rats = ['gsm', 'wcdma']
        for rat in rats:
            if rat_states.get(rat) in ['ALL_DISABLED']:
                self.admin_cli.unblock_rat(connection=connection, rat=rat.upper(), timeout=300)

    def _get_rat_states(self, connection):
        bts_info = self.admin_cli.get_bts_info(connection=connection, timeout=120)
        return bts_info.get('ratState', {})

    @log_as_robot_keyword
    def enable_esm1_state(self, connection, configuration):
        """
        Enables energy saving for all power groups.

        :param connection: Connection object to the BTS.
        :param configuration: Test configuration.
            Example: {'ESM1': {...}, 'ESM2': {...}}
        """

        delta = self.delta_helper.get_delta_for_esm1_state(connection=connection, configuration=configuration)
        self.admin_cli.perform_delta_recommissioning(delta_file=json.dumps(delta), connection=connection)
        if configuration['ESM1'].get('BLOCK_WCDMA_GSM_CELLS', False):
            self.block_wcdma_gsm_cells(connection=connection)

    @log_as_robot_keyword
    def enable_esm2_state(self, connection, configuration):
        """
        Enables deep sleep for all RUs and energy saving for all power groups if not already in ESM1.

        :param connection: Connection object to the BTS.
        :param configuration: Configuration dict for ESM2 state.
        """
        delta = self.delta_helper.get_delta_for_esm2_state(connection=connection, configuration=configuration)
        self.admin_cli.perform_delta_recommissioning(delta_file=json.dumps(delta), connection=connection)
        if configuration['ESM2'].get('BLOCK_WCDMA_GSM_CELLS', False):
            self.block_wcdma_gsm_cells(connection=connection)


class StatusChecker:
    """
    Provides status checking and waiting utilities for BTS, cells, and RUs.
    """
    def __init__(self, admin_cli):
        self.admin_cli = admin_cli
        self.cell_operation = GenericCellOperations()

    def check_all_cells_are_on_air(self, connection):
        """
        Checks if all BTS cells are in OnAir state.

        :param connection: Connection object/alias to the BTS.
        """

        self.cell_operation.verify_all_cells_are_onair(connection=connection,
                                                       skip_if_cell_in_energy_saving_state=False)

    @log_as_robot_keyword
    def get_cells_and_rus_statuses(self, connection):
        """
        Returns dicts of cell and RU statuses.

        :param connection: Connection object/alias to the BTS.
        :return: Tuple (cells_status, rus_status)
        """

        def normalize_energy_saving_state(state):
            if isinstance(state, str):
                return state[0].lower() + state[1:]
            return state

        bts_info = self.admin_cli.get_bts_info(connection=connection, timeout=90)
        cells_info = bts_info['cells']
        cells_status = {}
        rus_status = {}
        for rat in cells_info:
            if rat not in ['lte', 'nr']:
                continue
            for cell_info in cells_info[rat]:
                dist_name = cell_info['id']['configuration']
                cell_name = get_substring_from_dist_name(dist_name, start=-1, end=None)
                cell_status = cell_info['status']
                logging.debug(f"Cell {cell_name} ({rat}) status: {cell_status}")
                cells_status[cell_name] = {
                    'energy_saving_state': normalize_energy_saving_state(cell_info.get('energySavingState'))
                }
        rus_info = bts_info['radioModules']
        for ru_type in rus_info:
            for ru_info in rus_info[ru_type]:
                dist_name = ru_info['id']['configuration']
                ru_name = get_substring_from_dist_name(dist_name, start=-1, end=None)
                ru_status = ru_info['status']
                logging.debug(f"RU {ru_name} ({ru_type}) status: {ru_status}")
                rus_status[ru_name] = {'power_state': ru_status.get('powerState')}
        return cells_status, rus_status

    @log_as_robot_keyword
    def check_cells_and_rus_statuses_stable(self, connection, duration=4500, interval=14):
        """
        Checks that cells and RUs statuses remain stable for the given duration.
        Raises StatusChangedException if any status changes.

        :param connection: Connection object/alias to the BTS.
        :param duration: Duration in seconds to monitor. Example: 4500
        :param interval: Interval in seconds between checks. Example: 14
        """
        interval = time_to_seconds(interval)
        duration = time_to_seconds(duration)
        start_time = time.monotonic()
        end_time = start_time + duration
        initial_cells_status, initial_rus_status = self.get_cells_and_rus_statuses(connection)
        changes = []

        with RobotWrapper(wrap_name=f"Check Cells/RUs statuses for {duration} seconds", wrap_type="for") as wrapper:
            while time.monotonic() < end_time:
                wrapper.create_level(wrap_name="Check Cells/RUs statuses", wrap_type="foritem", level=2)
                current_cells_status, current_rus_status = self.get_cells_and_rus_statuses(connection)

                for cell_name, initial_status in initial_cells_status.items():
                    current_status = current_cells_status.get(cell_name)
                    if current_status != initial_status:
                        change = {
                            'timestamp': datetime.datetime.now().isoformat(),
                            'name': cell_name,
                            'initial': initial_status,
                            'current': current_status
                        }
                        changes.append(change)
                        logging.error(f"Status change detected for {cell_name}. Details: {change}")

                for ru_name, initial_status in initial_rus_status.items():
                    current_status = current_rus_status.get(ru_name)
                    if current_status != initial_status:
                        changes.append({
                            'timestamp': datetime.datetime.now().isoformat(),
                            'name': ru_name,
                            'initial': initial_status,
                            'current': current_status
                        })

                remaining_time = int(end_time - time.monotonic())
                if remaining_time <= 0:
                    break
                sleep_time = min(interval, remaining_time)
                logging.debug(f"Sleeping for {sleep_time} seconds before next status check...")
                time.sleep(sleep_time)

        if changes:
            summary = "\n".join([
                f"{c['timestamp']}: {c['name']} changed from {c['initial']} to {c['current']}"
                for c in changes
            ])
            raise StatusChangedException(
                f"Statuses changed during monitoring period:\n{summary}"
            )

    @log_as_robot_keyword
    def wait_till_cells_in_expected_state(self, connection, expected_cells_status, timeout=900, interval=30):
        """
        Waits until all power saving group cells are in energy saving state and remaining LTE/NR cells are notEnergySaving.

        :param connection: Connection object/alias to the BTS.
        :param expected_cells_status: Dict with cell names as keys and expected statuses as values.
            Example: {'LNCELL-1': 'energySaving', 'NRCELL-2': 'reducedEnergySaving'}
        :param timeout: Maximum time to wait in seconds. Example: 900
        :param interval: Time between checks in seconds. Example: 30
        """
        wait_till_succeeds(
            func=self.verify_cells_in_expected_state,
            exception_to_catch=IncorrectStatus,
            interval=interval,
            timeout=timeout,
            connection=connection,
            expected_cells_status=expected_cells_status,
        )

    @log_as_robot_keyword
    def verify_cells_in_expected_state(self, connection, expected_cells_status):
        """
        Verifies that all configured power saving group cells are in expected state and remaining
        LTE/NR cells are notEnergySaving.

        :param connection: Connection object/alias to the BTS.
        :param expected_cells_status: Dict with cell names as keys and expected statuses as values.
            Example: {'LNCELL-1': 'energySaving', 'NRCELL-2': 'reducedEnergySaving'}
        """
        cells_in_ess = []
        cells_not_in_ess = []
        remaining_cells_ok = []
        remaining_cells_not_ok = []
        bts_info = self.admin_cli.get_bts_info(connection=connection, timeout=90)
        cells_info = bts_info.get('cells', {})
        current_cells_status = {}
        not_energy_saving_expected = 'notEnergySaving'

        for rat in cells_info:
            for cell_info in cells_info[rat]:
                dist_name = cell_info['id']['configuration']
                cell_name = get_substring_from_dist_name(dist_name, start=-1, end=None)
                current_state = cell_info.get('energySavingState')
                current_cells_status[cell_name] = current_state

                if cell_name in expected_cells_status:
                    expected_state = expected_cells_status[cell_name]
                    if current_state and current_state.lower() == expected_state.lower():
                        cells_in_ess.append(cell_name)
                    else:
                        cells_not_in_ess.append(cell_name)
                else:
                    if rat in ('lte', 'nr'):
                        if current_state and current_state.lower() == not_energy_saving_expected.lower():
                            remaining_cells_ok.append(cell_name)
                        else:
                            remaining_cells_not_ok.append(cell_name)

        logging.debug(f"Expected status: {expected_cells_status}")
        logging.debug(f"Current status: {current_cells_status}")
        logging.debug(f"Cells in proper Energy Saving state: {cells_in_ess}")
        logging.debug(f"Cells NOT in proper energy saving state: {cells_not_in_ess}")
        logging.debug(f"Remaining cells (notEnergySaving) OK: {remaining_cells_ok}")
        logging.debug(f"Remaining cells NOT in notEnergySaving: {remaining_cells_not_ok}")

        if cells_not_in_ess or (expected_cells_status and not cells_in_ess):
            raise IncorrectStatus("Not all configured cells are in energy saving state.")
        if remaining_cells_not_ok:
            raise IncorrectStatus(
                f"Remaining cells (not in YAML config) must be notEnergySaving: {remaining_cells_not_ok}."
            )

    @log_as_robot_keyword
    def wait_till_rus_in_expected_state(self, connection, expected_rus_status=None, timeout=900, interval=30):
        """
        Waits until all RUs with enabled deep sleep mode are in SLEEP state.

        :param connection: Connection object/alias to the BTS.
        :param expected_rus_status: Dict with RU names as keys and expected statuses as values.
            Example: {'RMOD-1': 'SLEEP', 'RMOD-2': 'SLEEP_EXTREME'}
        :param timeout: Maximum time to wait in seconds. Example: 900
        :param interval: Time between checks in seconds. Example: 30
        """
        wait_till_succeeds(
            func=self.verify_rus_in_expected_state,
            exception_to_catch=IncorrectStatus,
            interval=interval,
            timeout=timeout,
            connection=connection,
            expected_rus_status=expected_rus_status
        )

    def verify_rus_in_expected_state(self, connection, expected_rus_status):
        """
        Verifies that all specified RUs are in expected state and remaining RUs (not in config) are AWAKE.

        :param connection: Connection object/alias to the BTS.
        :param expected_rus_status: Dict with RU names as keys and expected statuses as values.
        Example: {'RMOD-1': 'SLEEP', 'RMOD-2': 'SLEEP_EXTREME'}
        """
        expected_ru_names = set(expected_rus_status.keys()) if expected_rus_status else set()
        bts_info = self.admin_cli.get_bts_info(connection=connection, timeout=90)
        rus_info = bts_info['radioModules']
        rus_in_expected = []
        rus_not_in_expected = []
        remaining_rus_ok = []
        remaining_rus_not_ok = []
        current_rus_status = {}

        for ru_type in rus_info:
            for ru_info in rus_info[ru_type]:
                dist_name = ru_info['id']['configuration']
                ru_name = get_substring_from_dist_name(dist_name, start=-1, end=None)
                power_state = ru_info['status'].get('powerState')
                current_rus_status[ru_name] = power_state

                if power_state == 'UNAVAILABLE':
                    continue
                if ru_name in expected_ru_names:
                    if power_state == expected_rus_status[ru_name]:
                        rus_in_expected.append(ru_name)
                    else:
                        rus_not_in_expected.append(ru_name)
                else:
                    if power_state == 'AWAKE':
                        remaining_rus_ok.append(ru_name)
                    else:
                        remaining_rus_not_ok.append(ru_name)

        logging.debug(f"Expected RUs status: {expected_rus_status}")
        logging.debug(f"Current RUs status: {current_rus_status}")
        logging.debug(f"RUs in proper state: {rus_in_expected}")
        logging.debug(f"RUs NOT in proper state: {rus_not_in_expected}")
        logging.debug(f"Remaining RUs (AWAKE) OK: {remaining_rus_ok}")
        logging.debug(f"Remaining RUs NOT AWAKE: {remaining_rus_not_ok}")

        if rus_not_in_expected or (expected_ru_names and not rus_in_expected):
            raise IncorrectStatus("Not all configured RUs are in expected SLEEP state.")
        if remaining_rus_not_ok:
            raise IncorrectStatus(
                f"Remaining RUs (not in YAML config) must be AWAKE: {remaining_rus_not_ok}."
            )

    @log_as_robot_keyword
    def get_cells_params(self, connection):
        """
        Returns a dictionary {cell_name: pmax_value} for all cells.

        :param connection: Connection object/alias to the BTS.
        :return: Dict {cell_name: {'pmax': pmax_value}}
        """
        bts_info = self.admin_cli.get_bts_info(connection=connection, timeout=90)
        cells_info = bts_info.get('cells', {})
        result = {}
        for rat in cells_info:
            if rat not in ['lte', 'nr']:
                continue
            for cell_info in cells_info[rat]:
                dist_name = cell_info['id']['configuration']
                cell_name = get_substring_from_dist_name(dist_name, start=-1, end=None)
                cell_config = self.admin_cli.get_parameter_by_distname(
                    dist_name=dist_name, connection=connection, timeout=60
                )
                pmax = cell_config[0].get('parameters', {}).get('pMax')
                result[cell_name] = {'pmax': pmax}
        return result


class custom_resources:
    """
    Facade for robot keywords, delegates to thematic classes.
    """
    def __init__(self):
        self.admin_cli = admin()
        self.delta_helper = DeltaHelper(self.admin_cli)
        self.status_checker = StatusChecker(self.admin_cli)
        self.bts_state_manager = BtsStateManager(self.admin_cli, self.delta_helper, self.status_checker)

    # --- Robot keywords ---

    @log_as_robot_keyword
    def backup_initial_scf(self, connection):
        """
        Backs up the initial SCF file.
        """
        return self.delta_helper.backup_initial_scf(connection)

    @log_as_robot_keyword
    def recommission_to_initial_state(self, connection):
        """
        Recommissions the BTS to the initial state.
        """
        return self.delta_helper.recommission_to_initial_state(connection)

    @log_as_robot_keyword
    def go_to_proper_state(self, connection, test_state, configuration_yaml_file):
        """
        Changes the BTS state according to the specified test_state.
        Supported states: 'OnAirBefore', 'ESM1', 'ESM2', 'OnAirAfter'.

        :param connection: Connection object to the BTS.
        :param test_state: Desired BTS state ('OnAirBefore', 'ESM1', 'ESM2', 'OnAirAfter'). Example: 'ESM1'
        :param configuration_yaml_file: Path to YAML file with test configuration.
            Example: '/path/to/config.yaml'
        """
        return self.bts_state_manager.go_to_proper_state(connection, test_state, configuration_yaml_file)

    @log_as_robot_keyword
    def check_cells_and_rus_statuses_stable(self, connection, duration=4500, interval=14):
        """
        Checks that cells and RUs statuses remain stable for the given duration.
        Raises StatusChangedException if any status changes.

        :param connection: Connection object/alias to the BTS.
        :param duration: Duration in seconds to monitor. Example: 4500
        :param interval: Interval in seconds between checks. Example: 14
        """
        return self.status_checker.check_cells_and_rus_statuses_stable(connection, duration, interval)

    @log_as_robot_keyword
    def get_cells_and_rus_statuses(self, connection):
        """
        Returns dicts of cell and RU statuses.

        :param connection: Connection object/alias to the BTS.
        :return: Tuple (cells_status, rus_status)
        """
        return self.status_checker.get_cells_and_rus_statuses(connection)

    @log_as_robot_keyword
    def get_params_to_reporting(self, connection):
        """
        Returns a dictionary {cell_name: pmax_value} for all cells.

        :param connection: Connection object/alias to the BTS.
        :return: Dict {cell_name: pmax_value}
        """
        cells_statuses, rus_statuses = self.status_checker.get_cells_and_rus_statuses(connection)
        cells_params = self.status_checker.get_cells_params(connection)

        for cell_name in cells_params:
            cells_params[cell_name].update(cells_statuses.get(cell_name))

        return cells_params, rus_statuses
